static async logout(userId, rawRefreshToken, jti) {
  if (rawRefreshToken) {
    const tokenHash = hashToken(rawRefreshToken)
    await RefreshToken.updateOne({ tokenHash, userId }, { $set: { isRevoked: true, revokedReason: 'USER_LOGOUT', revokedAt: new Date() } })
  }
  if (jti) {
    await AccessTokenSession.deleteOne({ jti, userId })
  }
}

